public class StringUtils_join_TriageGen0Test {



    @Test
    public void testJoin_SeparatorNull() {
        // If separator is null, it should be treated as EMPTY (effectively no separator or empty string)
        // Note: The provided logic appends the separator first, then the element.
        // If separator is null -> EMPTY, result for [A, B] is "" + "A" + "" + "B" = "AB"
        Object[] array = {"A", "B"};
        assertEquals("When separator is null, treat as empty string", "AB", StringUtils.join(array, null, 0, 2));
    }












}

